window.kbPageData["views/entry/k-4abab460b45d8fe7"] = {"key":"entry/k-4abab460b45d8fe7","state":{"route":"entry/k-4abab460b45d8fe7"},"node":{"id":"k-4abab460b45d8fe7","mode":"k","title":"零碳园区和工厂建设","type":"概念与词义","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["生态环境"],"来源主题":["生态环境与能源"],"资料类别":["非时政"]},"directorySummary":"6.零碳园区和工厂建设\n零碳工厂建设是指通过技术创新、结构调整和管理优化 等减排措施，实现厂区内二氧\n化碳排放的持续降低、逐步趋 向于近零的过程。\n遵循原则：因业施策，系统推进。创新驱动，技术赋能。应减尽减，持续提升。统一规\n范，公开透明。\n主要目标：2026 年起，遴选一批零碳工厂，做好标杆引领。…","sources":[{"id":"b1ad1404e2a812d0","label":"零碳园区和工厂建设","topic":"生态环境与能源","category":"非时政","text":"6.零碳园区和工厂建设\n零碳工厂建设是指通过技术创新、结构调整和管理优化 等减排措施，实现厂区内二氧\n化碳排放的持续降低、逐步趋 向于近零的过程。\n遵循原则：因业施策，系统推进。创新驱动，技术赋能。应减尽减，持续提升。统一规\n范，公开透明。\n主要目标：2026 年起，遴选一批零碳工厂，做好标杆引领。到 2027 年，在汽车、锂电\n池、光伏、电子电器、轻工、机械、算力设施等行业领域，培育建设一批零碳工厂。到 2030\n年，将零碳工厂建设逐步拓展至钢铁、有色金属、石化化工、建材、纺织等行业领域，探索\n传统高载能产业脱碳新路径，推广零碳工厂设计、融资、改造、管理等综合服务模式和系统\n解决方案，大幅提升产品全生命周期和全产业链管理能力，实现工厂碳排放的稳步下降。\n——《关于开展零碳工厂建设工作的指导意见》","source":{"doc":"6cbfb01fe723bba64b75","first":47,"last":47,"page":47,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-4abab460b45d8fe7":[]}};
